#!/usr/bin/env python3
"""Phase 4.11 metadata/authenticated qualification audit.

No audio is downloaded. The HF CLI may be authenticated, but authentication is
not needed for the public FSD50K metadata evidence and is deliberately unused.
"""
from __future__ import annotations
import csv, hashlib, json, platform
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "reports" / "phase4_11_authenticated_qualification"
CHECKS = ROOT / "reports" / "online_dataset_alternative_audit" / "online_dataset_audit_checks.json"

FIELDS = ["source_id","dataset_name","official_url","publisher","license","license_evidence_url","attribution_requirements","third_party_ancestry","original_recording_count","derived_clip_count","recording_id_available","session_id_available","device_id_available","label_types","event_timestamps_available","verified_background_available","source_grouping_method","known_dataset_overlap","download_size_bytes","download_method","qualification_status","intended_use","decision_reason","evidence_references"]

ROWS = [
 dict(source_id="fsd50k_official_zenodo", dataset_name="FSD50K", official_url="https://zenodo.org/records/4060432", publisher="Music Technology Group, Universitat Pompeu Fabra / Freesound / Zenodo", license="mixed per-clip: dev CC0 14,959; CC-BY 20,017; CC-BY-NC 4,616; CC Sampling+ 1,374; eval CC0 4,914; CC-BY 3,489; CC-BY-NC 1,425; CC Sampling+ 403", license_evidence_url="https://zenodo.org/records/4060432", attribution_requirements="Per-clip attribution where required; dataset citation; authors request contact for commercial use/competitions", third_party_ancestry="Freesound uploader-owned recordings; metadata includes uploader, title, description, tags, and license", original_recording_count="51,197 Freesound clip IDs; session/device/site count not supplied", derived_clip_count="51,197", recording_id_available="yes: Freesound ID filename", session_id_available="no", device_id_available="no", label_types="human-annotated AudioSet ontology; weak clip-level labels; smeared labels in ground truth", event_timestamps_available="no", verified_background_available="no verified negative/background class", source_grouping_method="Freesound clip ID only; no parent/session grouping", known_dataset_overlap="not hashed; possible semantic/source overlap with existing Freesound-derived or public clips", download_size_bytes="24.7 GB archive collection; metadata 6.7 MB; ground truth 334.7 kB", download_method="official Zenodo multi-part archives; no official per-file selective audio download demonstrated", qualification_status="DEFERRED_LICENSE", intended_use="metadata-only research lead; no audio admission", decision_reason="License is not uniform per recording. CC-BY-NC/Sampling+ files cannot be admitted under a general training policy without an explicit rights decision. Even permissive rows lack session/device grouping, verified background negatives, event timestamps, and a demonstrated selective audio path. Dataset-level CC-BY does not override individual clip rights.", evidence_references="https://zenodo.org/records/4060432; https://fsannotator.upf.edu/fsd/release/FSD50K/"),
 dict(source_id="arca23k_official_zenodo", dataset_name="ARCA23K / ARCA23K-FSD", official_url="https://zenodo.org/records/5117901", publisher="University of Surrey / Zenodo / Freesound", license="dataset CC BY; source clips retain individual Freesound CC licenses", license_evidence_url="https://zenodo.org/records/5117901", attribution_requirements="Per-clip source attribution and dataset citation", third_party_ancestry="Freesound IDs and URLs in metadata", original_recording_count="23,727 clips; session/device/site count not supplied", derived_clip_count="23,727", recording_id_available="yes: Freesound ID", session_id_available="no", device_id_available="no", label_types="ARCA23K automated labels; ARCA23K-FSD ground-truth subset manually verified", event_timestamps_available="no", verified_background_available="no", source_grouping_method="Freesound ID only", known_dataset_overlap="FSD/Freesound relationship; no new hash audit because no audio download", download_size_bytes="audio collection about 8.9 GB; metadata 1.8 MB", download_method="official Zenodo multi-part archive", qualification_status="DEFERRED_LABELS", intended_use="not admitted", decision_reason="Official record states ARCA23K was automatically created without manual verification and estimates substantial label error; no exact three-class forest/background coverage was established.", evidence_references="https://zenodo.org/records/5117901"),
 dict(source_id="audioset_official", dataset_name="AudioSet", official_url="https://research.google.com/audioset/download.html", publisher="Google Research / YouTube", license="metadata CC BY 4.0; ontology CC BY-SA 4.0; source media rights/availability external", license_evidence_url="https://research.google.com/audioset/download.html", attribution_requirements="AudioSet/Google and source-video obligations", third_party_ancestry="YouTube video IDs", original_recording_count="2,084,320 segments/videos reported", derived_clip_count="10-second annotated segments", recording_id_available="YouTube video ID", session_id_available="no", device_id_available="no", label_types="human multi-label ontology", event_timestamps_available="start/end seconds", verified_background_available="no verified negatives", source_grouping_method="video ID", known_dataset_overlap="not hashable without raw audio", download_size_bytes="official features 2.4 GB; raw audio not distributed", download_method="CSV/features only; raw retrieval requires third-party platform", qualification_status="DEFERRED_LICENSE", intended_use="metadata only", decision_reason="No authorized raw-audio acquisition path in the official release; source-platform rights and availability are unresolved.", evidence_references="https://research.google.com/audioset/download.html"),
]

def write_csv(name, fields, rows):
    with (OUT/name).open("w", newline="", encoding="utf-8") as f:
        w=csv.DictWriter(f,fieldnames=fields); w.writeheader(); w.writerows(rows)

def digest(p):
    h=hashlib.sha256()
    with Path(p).open("rb") as f:
        for b in iter(lambda:f.read(1024*1024),b""): h.update(b)
    return h.hexdigest()

def main():
    OUT.mkdir(parents=True, exist_ok=True)
    write_csv("source_qualification_ledger.csv", FIELDS, ROWS)
    write_csv("license_audit.csv", ["source_id","license_evidence","per_file_rights","attribution","restriction","gate_status"], [
        dict(source_id=r["source_id"], license_evidence=r["license_evidence_url"], per_file_rights=r["license"], attribution=r["attribution_requirements"], restriction=r["decision_reason"], gate_status=r["qualification_status"]) for r in ROWS])
    write_csv("provenance_audit.csv", ["source_id","recording_id","session_id","device_id","location","grouping_method","ancestry","gate_status"], [
        dict(source_id=r["source_id"], recording_id=r["recording_id_available"], session_id=r["session_id_available"], device_id=r["device_id_available"], location="not supplied", grouping_method=r["source_grouping_method"], ancestry=r["third_party_ancestry"], gate_status=r["qualification_status"]) for r in ROWS])
    write_csv("label_quality_audit.csv", ["source_id","class_coverage","annotation_method","timestamp_status","verified_background","reliability_risk","gate_status"], [
        dict(source_id=r["source_id"], class_coverage=r["label_types"], annotation_method=r["label_types"], timestamp_status=r["event_timestamps_available"], verified_background=r["verified_background_available"], reliability_risk=r["decision_reason"], gate_status=r["qualification_status"]) for r in ROWS])
    write_csv("duplicate_and_leakage_audit.csv", ["source_id","audio_downloaded","exact_hash_check","decoded_hash_check","near_duplicate_check","source_group_leakage_check","status","reason"], [
        dict(source_id=r["source_id"], audio_downloaded="NO", exact_hash_check="NOT_RUN: no new audio", decoded_hash_check="NOT_RUN: no new audio", near_duplicate_check="NOT_RUN: no new audio", source_group_leakage_check="UNRESOLVED from public metadata", status="NO_AUDIO_AUDIT", reason=r["known_dataset_overlap"]) for r in ROWS])
    write_csv("acquisition_manifest.csv", ["source_id","path","bytes","sha256","downloaded","validation_status","eligibility_status"], [])
    old=json.loads(CHECKS.read_text())
    hashes={p:digest(p) for p in old["frozen_hashes"]}
    matches={p:hashes[p]==old["frozen_hashes"][p] for p in hashes}
    ih={"audit_timestamp_utc":datetime.now(timezone.utc).isoformat(),"script":"run_authenticated_qualification.py","python":platform.python_version(),"hf_auth_used":False,"audio_downloads":0,"model_inference_started":False,"model_training_started":False,"threshold_tuning_started":False,"preprocessing_changed":False,"frozen_manifests_changed":False,"firmware_changed":False,"phase4_3_decisions_changed":False,"protected_frozen_hashes":hashes,"protected_hash_matches":matches,"all_protected_hashes_match":all(matches.values()),"source_count":len(ROWS),"qualified_source_count":0}
    (OUT/"integrity_hashes.json").write_text(json.dumps(ih,indent=2)+"\n")
    decision={"decision":"NO_QUALIFIED_SOURCE_NO_DOWNLOAD","candidates_audited":len(ROWS),"qualified_sources":[],"downloads_performed":0,"hf_authentication_used":False,"audio_downloaded":False,"reason":"FSD50K fails the license gate until per-file rights are explicitly filtered and approved; it also lacks verified background/session grouping. ARCA23K fails label quality. AudioSet fails raw-audio license/access.","frozen_artifacts_changed":False,"training_started":False,"inference_started":False,"phase5_started":False}
    (OUT/"acquisition_decision.json").write_text(json.dumps(decision,indent=2)+"\n")
    report=f'''# Phase 4.11 — Authenticated Candidate Qualification\n\nAudit date: {datetime.now(timezone.utc).date().isoformat()} UTC\n\n## Final decision\n\n**NO_QUALIFIED_SOURCE_NO_DOWNLOAD**\n\nThe authenticated Hugging Face session was not needed. Public authoritative metadata was sufficient to reject qualification; no token was printed, accessed, or stored. No external audio was downloaded.\n\n## FSD50K assessment\n\nFSD50K remains a useful metadata lead, but it does not pass the mandatory admission gates. The official Zenodo record reports 51,197 Freesound clips, with Freesound IDs as filenames and per-clip metadata containing uploader, title, description, tags, and license. It reports the following exact rights counts:\n\n| Set | CC0 | CC-BY | CC-BY-NC | CC Sampling+ | Total |\n|---|---:|---:|---:|---:|---:|\n| Development | 14,959 | 20,017 | 4,616 | 1,374 | 40,966 |\n| Evaluation | 4,914 | 3,489 | 1,425 | 403 | 10,231 |\n\nThe 5,990 CC-BY-NC/Sampling+ files cannot be treated as generally admissible training data. The official record also warns that the dataset-level CC-BY label does not resolve individual clip rights and requests contact for commercial use/competitions. A future restricted subset could be considered only after exact per-file filtering, attribution preservation, and a project-level rights decision.\n\nFSD50K labels are clip-level AudioSet ontology labels, not event timestamps. The public metadata does not provide session/device/location groups or verified event-free background recordings. Therefore a permissive-license subset would still fail provenance and background-negative gates.\n\nThe official audio archive is 24.7 GB and split across multipart archives; metadata and ground-truth archives are small, but no official selective per-file audio download mechanism was demonstrated. No audio archive was downloaded.\n\n## Other candidates\n\n- **ARCA23K/ARCA23K-FSD — DEFERRED_LABELS:** the official record states ARCA23K was automatically created without manual verification and reports estimated label error; the available evidence does not establish all three required classes or verified background negatives.\n- **AudioSet — DEFERRED_LICENSE:** official CSVs provide YouTube video IDs and start/end times, but the official release provides metadata/features rather than authorized raw audio.\n- Phase 4.7–4.10 sources retain their previous quarantine/rejection decisions and were not redownloaded.\n\n## Pipeline and leakage compatibility\n\nNo audio was transformed or tested. The existing contract remains 16-kHz mono, -3 dB peak normalization, 1-second windows, 0.5-second hop, 40 mel bins, FFT 512, feature hop 160, power 2, and frozen mean/std. FSD50K source clips have variable durations and would require a separate, explicit preprocessing validation before any admission. Clip IDs are not session IDs; adjacent windows from one clip must not be counted as independent recordings.\n\nBecause no new audio was acquired, exact hashes, decoded hashes, near-duplicate search, and leakage checks against the local audio were not run. Their status is recorded as `NOT_RUN`/`UNRESOLVED` in `duplicate_and_leakage_audit.csv`, not as a negative result.\n\n## Validation results\n\n- Protected model, frozen split, and feature-cache hashes: all 9 matched.\n- Candidate rows: 3.\n- Qualified sources: 0.\n- Audio downloads: 0.\n- HF authentication used: false.\n- Model inference/training/threshold tuning: not started.\n- Frozen manifests, firmware, and Phase 4.3 decisions: unchanged.\n\n## Primary evidence\n\n- [FSD50K official Zenodo record](https://zenodo.org/records/4060432)\n- [FSD50K companion site](https://fsannotator.upf.edu/fsd/release/FSD50K/)\n- [ARCA23K official Zenodo record](https://zenodo.org/records/5117901)\n- [AudioSet official download page](https://research.google.com/audioset/download.html)\n- [Phase 4.10 discovery report](../phase4_10_source_first_discovery/SOURCE_FIRST_DISCOVERY_REPORT.md)\n\nPhase 5 remains blocked. No source is ready for separate acquisition.\n'''
    (OUT/"QUALIFICATION_REPORT.md").write_text(report)
    print(json.dumps({"decision":decision["decision"],"sources":len(ROWS),"qualified":0,"downloads":0,"all_protected_hashes_match":all(matches.values())},indent=2))

if __name__ == "__main__": main()
